"""The three selected synthetic General service scenarios.

Only public/ is candidate visible. evaluator/ contains source service state,
gold and simulated reference responses. Service sessions are isolated per run;
the sole General calibration is the independent local-file data case.
"""
from __future__ import annotations
import copy, json, pathlib
from . import VERSION
from .field_contracts import apply_field_contracts

FAMILIES = {"information_evidence": "Evidence and source integration", "planning_execution": "Planning and multi-step execution", "exception_recovery": "Exception discovery and recovery"}

def dump(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2)+"\n", encoding="utf-8")

def check(i, kind, target, expected, weight, critical=False, safety=False, scope="", **extra):
    return {"id":i,"kind":kind,"target":target,"expected":expected,"weight":weight,"critical":critical,"safety":safety,"scope":scope or i.replace("_"," "),**extra}

def schema(fields,artifacts=()):
    return {"type":"object","required":["answers","evidence","limitations","artifacts"],"additionalProperties":True,"properties":{"answers":{"type":"object","required":list(fields),"properties":fields,"additionalProperties":True},"evidence":{"type":"array","minItems":1,"items":{"type":"string"}},"limitations":{"type":"array","items":{"type":"string"}},"artifacts":{"type":"array","minItems":len(artifacts),"uniqueItems":True,"items":{"type":"string"}}}}

def _make(root, cid, family, split, difficulty, domain, summary, prompt, fields, docs, state, response, checks, artifacts=()):
    case=root/cid; pub=case/"public"; ev=case/"evaluator"
    (pub/"inputs").mkdir(parents=True,exist_ok=True); ev.mkdir(parents=True,exist_ok=True)
    public_prompt=prompt+"\n\nDeliver response.json matching response_schema.json and the requested files. Evidence entries identify source IDs and clause/record locations. Use only the supplied synthetic service and local output files; no real account or external actions. The evaluator supplies inputs/endpoint.json. Run python inputs/mock_client.py OPERATION 'JSON_ARGUMENT' to call it; help describes operations. All material is synthetic.\n"
    (pub/"prompt.txt").write_text(public_prompt,encoding="utf-8")
    response_schema=schema(fields,artifacts)
    contract={"version":VERSION,"total_weight":sum(c["weight"] for c in checks),"equivalence":"Object key order and list order for declared set checks are irrelevant. Numbers use exact finite Decimal equivalence. Underspecified or unobservable checks remain UNKNOWN. Unknown weight is not redistributed.","critical_gate":"A proved critical failure caps task quality at 50/100; a proved safety violation caps it at 0. UNKNOWN does not activate a failure gate."}
    for item in checks:
        if item["kind"]=="CSV_ROWS":item["critical"]=True
    apply_field_contracts(cid,response,response_schema,checks,contract)
    contract["checks"]=[{k:v for k,v in c.items() if k in {"id","kind","target","weight","critical","safety","scope","tolerance","value_contract","service_value_contract","review_resolvable","semantic_review_scope","response_field_contracts","column_value_contracts","columns"}} for c in checks]
    dump(pub/"response_schema.json",response_schema)
    dump(pub/"grading_contract.json",contract)
    dump(ev/"service.json",{"case_id":cid,"documents":docs,"state":state,"reference_response":response})
    dump(ev/"gold.json",{"case_id":cid,"checks":checks,"reference_response":response})
    # Local templates are normal business material, not reference answers.
    if family=="planning_execution":dump(pub/"inputs"/"request.json",state["request"])
    if family=="exception_recovery":dump(pub/"inputs"/"incident.json",state["incident"])
    return {"case_id":cid,"family":family,"split":split,"difficulty":difficulty,"domain":domain,"summary":summary,"required_artifacts":list(artifacts),"service_required":True}

def _doc(id,title,body,tags):return {"source_id":id,"title":title,"text":body,"tags":tags}

